import {DRAWING_PAPERS,normalizeDrawingOptions} from './drawing-options.js';
import {buildDrawings,packageDrawings} from './drawings.js';
import {drawingSVG,loadDrawingFont} from './drawing-format.js';

export function initDrawingUI(api,{build=buildDrawings,pack=packageDrawings,loadFont=loadDrawingFont}={}){
 let closeActive=()=>{};
 function open(){
  closeActive();let options=normalizeDrawingOptions(api.project().drawings),busy=false,disposed=false,controller=null,result=null,urls=[],previewURL=null,index=0;
  const esc=api.esc,field=(label,name,entries)=>`<label>${label}<select name="${name}">${entries.map(([value,title])=>`<option value="${value}"${String(options[name])===String(value)?' selected':''}>${title}</option>`).join('')}</select></label>`,input=(label,name)=>`<label>${label}<input name="${name}" value="${esc(options[name])}" maxlength="${name==='revision'?24:80}"></label>`;
  api.openModal('Engineering drawing package',`<div id="drawingPanel"><p class="drawing-intro">An isometric assembly view, six dimensioned orthographic views, and detailed component and surface sheets.</p><div class="drawing-layout"><form id="drawingSettings"><span class="eyebrow">DRAWING SETUP</span>${input('Drawing number','number')}<div class="fields two">${input('Revision','revision')}${field('Units','units',[['project','Project units'],['mm','Millimeters'],['in','Inches']])}</div>${field('Paper · landscape','paper',Object.entries(DRAWING_PAPERS).map(([k,v])=>[k,v.name]))}<div class="fields two">${field('Scale','scale',[[0,'Auto fit'],[1,'1:1'],[.5,'1:2'],[.25,'1:4'],[.2,'1:5'],[.1,'1:10'],[2,'2:1'],[5,'5:1']])}${field('Decimal places','precision',[[0,'0'],[1,'1'],[2,'2'],[3,'3'],[4,'4']])}</div><details open><summary>Sheets & detail</summary><div class="stack">${[['partDetails','Component & enclosure detail sheets'],['surfaceDetails','Cutout, decal & lettering layouts'],['wiring','Wiring dimensions & route coordinates'],['includeHidden','Include hidden physical parts'],['hiddenLines','Show hidden edges as dashed lines']].map(([k,label])=>`<label class="check"><input type="checkbox" name="${k}"${options[k]?' checked':''}>${label}</label>`).join('')}</div></details><details><summary>Title block</summary>${input('Prepared by','preparedBy')}</details><button id="drawingGenerate" type="submit" class="primary wide">Generate drawing package</button><button id="drawingCancel" type="button" class="wide" hidden>Cancel generation</button><p class="fine">Dimensions come from the model and saved joint pose. Tolerances and manufacturing specifications remain explicit design inputs.</p></form><section class="drawing-main" aria-label="Drawing preview"><div id="drawingEmpty" class="drawing-empty"><strong>Ready for the drawing board.</strong><p>Choose the sheet size and generate the package.<br>Geometry, dimensions and downloads stay local.</p><div class="drawing-view-list">ISO · TOP · BOTTOM · LEFT · RIGHT · FRONT · BACK</div></div><div id="drawingResult" hidden><div class="drawing-toolbar"><button id="drawingPrev" type="button" aria-label="Previous drawing sheet">←</button><select id="drawingSheet" aria-label="Drawing sheet"></select><button id="drawingNext" type="button" aria-label="Next drawing sheet">→</button></div><div class="drawing-preview"><img id="drawingPreview" alt="Engineering drawing preview"></div><div class="drawing-downloads"><a id="drawingPDF" class="movie-download" aria-disabled="true">Download PDF</a><a id="drawingZIP" class="drawing-zip" aria-disabled="true">Drawing package ZIP</a></div><p class="fine">ZIP includes the PDF, every sheet as SVG, and a complete numeric dimension register. Print at 100% using the selected paper size.</p></div><p id="drawingStatus" role="status">Ready to generate.</p><p id="drawingError" role="alert" class="form-error" hidden></p></section></div></div>`);
  const modal=document.querySelector('#modal'),panel=document.querySelector('#drawingPanel'),$=s=>panel.querySelector(s),form=$('#drawingSettings');modal.classList.add('drawing-modal');
  function controls(){for(const el of form.querySelectorAll('input,select'))el.disabled=busy;$('#drawingGenerate').disabled=busy;$('#drawingGenerate').textContent=result?'Regenerate package':'Generate drawing package';$('#drawingCancel').hidden=!busy;}
  function clear(){for(const url of urls)URL.revokeObjectURL(url);urls=[];if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null;result=null;$('#drawingPreview').removeAttribute('src');for(const id of ['drawingPDF','drawingZIP']){$('#'+id).removeAttribute('href');$('#'+id).setAttribute('aria-disabled','true');}$('#drawingResult').hidden=true;$('#drawingEmpty').hidden=false;}
  function close(){if(disposed)return;disposed=true;controller?.abort();clear();modal.classList.remove('drawing-modal');modal.removeEventListener('close',close);observer?.disconnect();}closeActive=close;modal.addEventListener('close',close);const observer=typeof MutationObserver==='undefined'?null:new MutationObserver(()=>{if(!panel.isConnected)close();});observer?.observe(document.querySelector('#modalBody'),{childList:true});
  function show(i){if(!result)return;index=Math.max(0,Math.min(result.sheets.length-1,i));const s=result.sheets[index];if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(new Blob([drawingSVG(s)],{type:'image/svg+xml'}));$('#drawingPreview').src=previewURL;$('#drawingPreview').alt=`Sheet ${index+1}: ${s.title}`;$('#drawingSheet').value=String(index);$('#drawingPrev').disabled=index===0;$('#drawingNext').disabled=index===result.sheets.length-1;}
  form.addEventListener('change',()=>{if(busy)return;clear();$('#drawingStatus').textContent='Settings changed. Generate the updated drawing set.';controls();});
  form.onsubmit=async e=>{e.preventDefault();if(busy)return;$('#drawingError').hidden=true;try{
   const next={...options};for(const el of form.querySelectorAll('[name]'))next[el.name]=el.type==='checkbox'?el.checked:['scale','precision'].includes(el.name)?Number(el.value):el.value;options=normalizeDrawingOptions(next);clear();busy=true;controls();controller=new AbortController();api.commit(()=>api.project().drawings=options,{rebuild:false,inspector:false});const snapshot=structuredClone(api.project());
   const [built,font]=await Promise.all([build(snapshot,options,{signal:controller.signal,onProgress:message=>{if(!disposed)$('#drawingStatus').textContent=message;}}),loadFont(controller.signal)]);controller.signal.throwIfAborted();if(disposed)return;$('#drawingStatus').textContent='Packaging PDF and SVG sheets…';await new Promise(r=>setTimeout(r,0));controller.signal.throwIfAborted();const output=await pack(built,font,controller.signal);controller.signal.throwIfAborted();if(disposed)return;result=built;const stem=(snapshot.title+'-'+options.number+'-rev-'+options.revision).replace(/[^a-z0-9_-]+/gi,'-').slice(0,140)||'mockupbench';
   for(const [id,bytes,type,ext] of [['drawingPDF',output.pdf,'application/pdf','pdf'],['drawingZIP',output.zip,'application/zip','zip']]){const url=URL.createObjectURL(new Blob([bytes],{type}));urls.push(url);$('#'+id).href=url;$('#'+id).download=stem+'-drawings.'+ext;$('#'+id).setAttribute('aria-disabled','false');}
   $('#drawingSheet').innerHTML=result.sheets.map((s,i)=>`<option value="${i}">${i+1}. ${esc(s.title)}</option>`).join('');$('#drawingEmpty').hidden=true;$('#drawingResult').hidden=false;show(0);$('#drawingStatus').textContent=`${result.sheets.length} sheets ready · ${result.units} · ${DRAWING_PAPERS[options.paper].name}`;
  }catch(err){controller?.abort();if(disposed)return;if(err.name==='AbortError')$('#drawingStatus').textContent='Generation canceled. Your model is unchanged.';else{$('#drawingError').hidden=false;$('#drawingError').textContent=err.message||String(err);$('#drawingStatus').textContent='Could not generate the package. Adjust the settings and retry.';}}finally{busy=false;if(!disposed)controls();}};
  $('#drawingCancel').onclick=()=>controller?.abort();$('#drawingPrev').onclick=()=>show(index-1);$('#drawingNext').onclick=()=>show(index+1);$('#drawingSheet').onchange=()=>show(Number($('#drawingSheet').value));controls();
 }
 return {open,close:()=>closeActive()};
}
